                    sprite = sprite->next;
                }

                for (int bucket = 0xff; bucket >= 0; --bucket) {
                    SpriteDepthNode* node = g_sprite_depth_buckets[bucket];
                    if (node != 0) {
                        do {
                            if ((node->sprite->flags & SPRITE_FLAG_ORIENT_TO_MOTION) != 0) {
                                node->sprite->BuildTail(
                                    &viewports[camera_index].camera->view_matrix);
                            }
                            draw_sprite_quad(&node->position, node->sprite);
                            node = node->next;
                        } while (node != 0);
                        g_sprite_depth_buckets[bucket] = node;
                    }
                }

                end_sprite_depth_render_state();
                begin_overlay_render_state();
                FontPrintRender(viewports[camera_index].flags);
                end_overlay_render_state();

                if ((viewports[camera_index].flags & 2) == 0 &&
                    post_sprite_count != 0) {
                    render_camera(
                        viewports[camera_index].viewport_x,
                        viewports[camera_index].viewport_y,
                        viewports[camera_index].viewport_width,
                        viewports[camera_index].viewport_height,
                        viewports[camera_index].camera->fov_degrees,
                        &viewports[camera_index].camera->transform,
                        &viewports[camera_index].camera->view_matrix,
                        viewports[camera_index].draw_world,
                        1);

                    RenderableBod** post_cursor =
                        g_post_sprite_bods + post_sprite_count;
                    int replay_count = post_sprite_count;
                    post_sprite_count = 0;
                    rendered_bod_count += replay_count;
                    do {
                        --post_cursor;
                        unsigned int bod_flags = (*post_cursor)->list_flags;
                        if ((bod_flags & BOD_FLAG_USE_TRANSFORM) != 0) {
                            render_object(
                                (*post_cursor)->object,
                                &(*post_cursor)->transform,
                                (*post_cursor)->render_arg_1c,
                                (*post_cursor)->render_arg_20,
                                &(*post_cursor)->color,
                                (char)(*post_cursor)->IsAfterSprites());
                        } else {
                            transform.position = (*post_cursor)->position;
                            render_object(
                                (*post_cursor)->object,
                                &transform,
                                (*post_cursor)->render_arg_1c,
                                (*post_cursor)->render_arg_20,
                                &(*post_cursor)->color,
                                (char)(*post_cursor)->IsAfterSprites());
                        }
                        --replay_count;
                    } while (replay_count != 0);
                }
            }

            ++camera_cursor;
            --remaining_cameras;
        } while (remaining_cameras != 0);
    }

    ::noop_runtime_ai();
}
